def _check_domain(domain, perm):
    if len(domain) != len(perm):
        raise ValueError(f"Domain and permutation must have the same length. Got {len(domain)} and {len(perm)}. ")

    seen = set()
    for i in domain:
        if i in seen:
            raise ValueError(f"Domain has duplicate elements: {domain}")
        seen.add(i)

    perm_set = set(perm)
    if len(perm_set) != len(perm):
        raise ValueError(f"Permutation has duplicate elements: {perm}")

    if domain != perm_set:
        raise ValueError(f"Domain and permutation elements mismatch. Got {domain} and {perm_set}")


