class Permutation(BaseElement):

    def __init__(self, perm: Iterable[int], _act: bool = True) -> None:
        if not _act:
            return

        if isinstance(perm, Permutation):
            self._perm = perm._perm
            self.domain = perm.domain
            return

        perm_list = list(perm)
        if len(set(perm_list)) != len(perm_list):
            raise ValueError(f"Permutation cannot have duplicate elements: {perm_list}")

        self._perm = tuple(perm_list)
        self.domain = tuple(range(len(self._perm)))
        self._act = _act

    def __eq__(self, other) -> bool:
        if not isinstance(other, Permutation):
            return NotImplemented
        return self._perm == other._perm

    def __hash__(self) -> int:
        return hash(self._perm)

    def __lt__(self, other) -> bool:
        if not isinstance(other, Permutation):
            return NotImplemented
        return self._perm < other._perm

    def __len__(self) -> int:
        return len(self._perm)

    def __repr__(self) -> str:
        return f"Permutation({self._perm})"

    def __str__(self) -> str:
        return str(self._perm)

    def __getitem__(self, index: int) -> int:
        return self._perm[index]

    def __setitem__(self, index: int, value: int) -> None:
        raise FrozenError("Permutation object is immutable")

    def __pow__(self, n: int) -> "Permutation":
        if not isinstance(n, int):
            return NotImplemented

        if n == 0:
            return Permutation(range(len(self)))

        if n < 0:
            raise NotImplementedError("Negative powers are not supported.")

        if n == 1:
            return self

        if self in _perm_cache:
            return _perm_cache[self]

        res = self
        for _ in range(n - 1):
            res = res * self
        _perm_cache[self] = res
        return res

    def __invert__(self) -> "Permutation":
        if self in _perm_cache:
            return _perm_cache[self]

        inv_perm = [0] * len(self)
        for i, p in enumerate(self):
            inv_perm[p] = i

        res = Permutation(inv_perm)
        _perm_cache[self] = res
        return res

    def __mul__(self, other: "Permutation") -> "Permutation":
        if not isinstance(other, Permutation):
            return NotImplemented

        if len(self) != len(other):
            raise ValueError("Permutations must have the same length to be multiplied.")

        res = [0] * len(self)
        for i, p in enumerate(self):
            res[i] = other[p]

        return Permutation(res)

    def __xor__(self, other: "Permutation") -> "Permutation":
        if not isinstance(other, Permutation):
            return NotImplemented

        if len(self) != len(other):
            raise ValueError("Permutations must have the same length to be XORed.")

        res = [0] * len(self)
        for i, p in enumerate(self):
            res[i] = other[p] ^ self[i] # Wrong index

        return Permutation(res)

    @staticmethod
