        return Permutation(perm)

    @classmethod
    def _new(cls, perm: Iterable[int]) -> "Permutation":
        from .base import Poly  # Avoid circular import
        return cls(perm)

    @classmethod
    def from_permutation(cls, perm: Iterable[int]) -> "Permutation":
        return cls._new(perm)

    @classmethod
    def from_iterable(cls, iterable: Iterable[int]) -> "Permutation":
        return cls._new(iterable)

    @classmethod
    def from_array(cls, arr: np.ndarray) -> "Permutation":
        return cls._new(arr)

    @classmethod
    def from_list(cls, lst: List[int]) -> "Permutation":
        return cls._new(lst)

    @classmethod
    def from_tuple(cls, tup: Tuple[int, ...]) -> "Permutation":
        return cls._new(tup)

    def inverse(self) -> "Permutation":
        return self.__invert__()

    def conjugate(self, other: "Permutation") -> "Permutation":
        return self * other * self.inverse()

    def commutator(self, other: "Permutation") -> "Permutation":
        return self * other * self.inverse() * other.inverse()

    def _to_tuple(self) -> Tuple[int, ...]:
        return self._perm

    def _to_list(self)-> List[int]:
        return list(self._perm)

    def _to_array(self) -> np.ndarray:
        return np.array(self._perm)

    def _is_identity(self) -> bool:
        return all(i == p for i, p in enumerate(self))

    def _get_cycles(self) -> Generator[List[int], None, None]:
        visited = [False] * len(self)
        for i in range(len(self)):
            if not visited[i]:
                cycle = []
                j = i
                while not visited[j]:
                    visited[j] = True
                    cycle.append(j)
                    j = self[j]
                yield cycle

    def _get_transpositions(self) -> List[Tuple[int, int]]:
        transpositions = []
        visited = [False] * len(self)
        for i in range(len(self)):
            if not visited[i]:
                cycle = []
                j = i
                while not visited[j]:
                    visited[j] = True
                    cycle.append(j)
                    j = self[j]
                if len(cycle) > 1:
                    # Convert cycles to transpositions
                    for k in range(1, len(cycle)):
                        transpositions.append(tuple(sorted((cycle[0], cycle[k]))))
        return transpositions

    def _get_sign(self) -> int:
        num_transpositions = len(self._get_transpositions())
        return (-1)**num_transpositions

    def _is_even(self) -> bool:
        return self._get_sign() == 1

    def _is_odd(self) -> bool:
        return self._get_sign() == -1

