    def __call__(self, index: int) -> int:
        return self[index]

    def __rshift__(self, other: int) -> "Permutation":
        if not isinstance(other, int):
            return NotImplemented
        if other < 0:
            raise ValueError("Right shift must be non-negative")
        return self._apply_shift(other)

    def __lshift__(self, other: int) -> "Permutation":
        if not isinstance(other, int):
            return NotImplemented
        if other < 0:
            raise ValueError("Left shift must be non-negative")
        return self._apply_shift(-other)

    def _apply_shift(self, shift: int) -> "Permutation":
        if shift == 0:
            return self
        new_perm = [0] * len(self)
        for i, p in enumerate(self):
            idx = (i + shift) % len(self)
            new_perm[idx] = p
        return Permutation(new_perm)

    def _get_cycle_tuple(self) -> Tuple[int, ...]:
        return tuple(self._perm)

    def _get_cycle_list(self) -> List[int]:
        return list(self._perm)

    def _get_cycle_array(self) -> np.ndarray:
        return np.array(self._perm)

    def _get_fixed_points(self) -> List[int]:
        return [i for i, p in enumerate(self) if i == p]

    def _get_num_fixed_points(self) -> int:
        return len(self._get_fixed_points())

    def is_identity(self) -> bool:
        return self._is_identity()

    def is_even(self) -> bool:
