class PermutationGroup(BaseCollection):
    """A collection of permutations that forms a group."""
    def __init__(self, perms: Iterable[Permutation]) -> None:
        self.perms = list(perms)
        self.order = len(self.perms)

    def __iter__(self) -> Iterator[Permutation]:
        return iter(self.perms)

    def __len__(self) -> int:
        return self.order

    def __getitem__(self, index: int) -> Permutation:
        return self.perms[index]

    def __contains__(self, perm: Permutation) -> bool:
        return perm in self.perms

    def __repr__(self) -> str:
        return f"PermutationGroup({self.perms})"

    def __eq__(self, other) -> bool:
        if not isinstance(other, PermutationGroup):
            return NotImplemented
        return self.perms == other.perms

    def generating_set(self) -> List[Permutation]:
        return self.perms

    def add(self, perm: Permutation) -> None:
        if perm not in self.perms:
            self.perms.append(perm)
            self.order += 1

    def remove(self, perm: Permutation) -> None:
        if perm in self.perms:
            self.perms.remove(perm)
            self.order -= 1

    def is_subgroup(self, other: "PermutationGroup") -> bool:
        return all(p in other for p in self.perms)

    def is_identity_group(self) -> bool:
        return self.order == 1 and self.perms[0].is_identity()


