def fix_mathematical_operations():
    # Update mathematical operations to use type(self)._af_new
    Permutation.__mul__ = lambda self, other: type(self)(Permutation(self) * other)
    Permutation.__pow__ = lambda self, n: type(self)(Permutation(self) ** n)
    Permutation.__invert__ = lambda self: type(self)(~Permutation(self))
    Permutation.__xor__ = lambda self, other: type(self)(Permutation(self) ^ other)

