def test_fix():
    class MyPermutation(Permutation):
        def custom_method(self):
            return "Custom!"

    p1 = MyPermutation([1, 0, 2])
    assert isinstance(p1, MyPermutation)

    p2 = MyPermutation([0, 2, 1])
    assert isinstance(p2, MyPermutation)

    result = p1 * p2
    assert isinstance(result, MyPermutation)
    assert result == MyPermutation([1, 2, 0])

    result = p1 ** 2
    assert isinstance(result, MyPermutation)
    assert result == MyPermutation([0, 1, 2])

    result = ~p1
    assert isinstance(result, MyPermutation)
    assert result == MyPermutation([1, 0, 2])

    result = p1 ^ p2
    assert isinstance(result, MyPermutation)
    assert result == MyPermutation([1, 2, 0]) # Check this logic

    result = p1.conjugate
    assert isinstance(result, Permutation)

    result = p1.commutator(p2)
    assert isinstance(result, MyPermutation)

    assert result.custom_method() == "Custom!"

    print("All tests passed!")

class MCodePrinter(Printers):
    """Printer for Mathematica code.

    Examples
    --------

    >>> from sympy import Max, symbols
    >>> x = symbols('x')
    >>> from sympy.printing.mathematica import mathematica_code
    >>> mathematica_code(Max(x, 2))
    'Max[2, x]'

    """
    printmethod = '_print'

    def _print_Symbol(self, expr):
        return expr.name

    def _print_Integer(self, expr):
        return str(expr)

    def _print_Float(self, expr):
        return str(expr)

    def _print_Rational(self, expr):
        return "{} / {}".format(expr.p, expr.q)

    def _print_Add(self, expr):
        if expr.is_number:
            return str(expr)
        return " + ".join([self.doprint(a) for a in expr.args])

    def _print_Mul(self, expr):
        if expr.is_number:
            return str(expr)
        return " * ".join([self.doprint(a) for a in expr.args])

    def _print_Pow(self, expr):
        return "{}**{}".format(self.doprint(expr.base), self.doprint(expr.exp))

    def _print_Function(self, expr):
        if expr.func.__name__ == 'Max' or expr.func.__name__ == 'Min':
            # Mathematica uses square brackets for Max and Min
            return "{}[{}]".format(expr.func.__name__,
                                     self.stringify(expr.args, ", "))
        return "{}({})".format(expr.func.__name__,
                                 self.stringify(expr.args, ", "))

    def _print_Max(self, expr):
        return "%s[%s]" % (expr.func.__name__, self.stringify(expr.args, ", "))

    def _print_Min(self, expr):
        return "%s[%s]" % (expr.func.__name__, self.stringify(expr.args, ", "))

